def construir_dados_102_300(D):
    """Monta o dict {chave: dados} para os 199 domínios (102–300) usando a fábrica dominios.D."""
    dados = {}
    for setor_idx, chave, ent, ident, recurso, qtd, preco, unidade in _SPECS_102_300:
        precos, variantes, extras = _PERFIS_SETOR[setor_idx]
        cat_unid = unidade.split("(")[0].strip() or "unidade"
        rotulo_rec = recurso.split(":")[1]
        rot_cap = rotulo_rec.capitalize()
        categorias = (
            f"{cat_unid}: {ent}Basico = {ent} básico 100; "
            f"{ent}Padrao = {ent} padrão 180; "
            f"{ent}Avancado = {ent} avançado 320; "
            f"{ent}Especial = {ent} especial 240"
        )
        painel = (
            f"{rot_cap} | disponível | EM USO | Registrar | (em uso) | "
            f"LOTADO - nenhum(a) {rotulo_rec} disponível | {rotulo_rec}(s) disponível(is)"
        )
        dados[chave] = D(
            ident, recurso, qtd, preco, unidade, precos, variantes,
            categorias, extras, f"Paga{ent}", painel,
        )
    return dados
